import{_ as o}from"./chunks/nahrada_uzivatele.RPcfS4Lh.js";import{_ as e,o as n,c as i,aa as t}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/cs/news/nastaveni_podpisu3.png",r="/buildary-help-preview/media/cs/news/umisteni_mapa.png",d="/buildary-help-preview/media/cs/news/clen_pt.png",l="/buildary-help-preview/media/cs/news/sk_registr.png",p="/buildary-help-preview/media/cs/news/dic_dph.png",v="/buildary-help-preview/media/cs/news/kalendar.png",u="/buildary-help-preview/media/cs/news/kopirovani_deniku_id.png",m="/buildary-help-preview/media/cs/news/vyhledani3.png",k="/buildary-help-preview/media/cs/news/spp_import_vysledek.png",c="/buildary-help-preview/media/cs/news/spp_chyby_rozpocet.png",_=JSON.parse('{"title":"Novinky verze 4.0 ve zkratce","description":"","frontmatter":{"title":"Novinky verze 4.0 ve zkratce","wiki":"cs:news:vrsion_4.0"},"headers":[],"relativePath":"news/version_4-0.md","filePath":"news/version_4-0.md","lastUpdated":1794209661000}'),h={name:"news/version_4-0.md"};function y(z,a,b,j,g,f){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="novinky-verze-4-0-ve-zkratce" tabindex="-1">Novinky verze 4.0 ve zkratce <a class="header-anchor" href="#novinky-verze-4-0-ve-zkratce" aria-label="Permalink to &quot;Novinky verze 4.0 ve zkratce&quot;">​</a></h1><p>Informace o novinkách se od této verze budete dovídat přímo v aplikaci v Nastavení vašeho profilu (ikona panáčka vpravo nahoře v tmavé liště), a zároveň v Nápovědě k celé aplikaci (ikona otazníku vpravo nahoře v tmavé liště)</p><ul><li>Změny v podepisování</li><li>Podpis kvalifikovaným certifikátem</li><li>Podpis certifikátem Buildary</li><li>Vzdálené podepisování RemoteSign</li><li>Real-time aktualizace obrazovek</li><li>Vyhledávání v rejstříku Slovenských organizací a DIČ DPH</li><li>Zadávání do mapy adresou</li><li>Přidávání uživatele do více deníků najednou</li><li>Kopírování záznamů mezi deníky různých staveb</li><li>Vyhledávání nepodepsaných záznamů</li><li>Import rozpočtu s označením chybných hodnot</li><li>Hromadné přiřazení do deníků a zneplatnění uživatele</li></ul><h2 id="zmeny-v-podepisovani" tabindex="-1">Změny v Podepisování <a class="header-anchor" href="#zmeny-v-podepisovani" aria-label="Permalink to &quot;Změny v Podepisování&quot;">​</a></h2><p>Podepisování v Buildary zažívá doslova revoluci! A to jak co do kvality, tak také do kvantity. Dlouho vás trápilo podepisování záznamů samostatně. Našli jsme způsob, jak vám podepisování co nejvíce zjednodušit. Kromě toho, že si nyní můžete vybrat z několika podpisových variant, nově také máte možnost <strong>podepsat najednou celý měsíc</strong>.</p><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+s+'" alt="" width="600" loading="lazy"><br></p></div><p><strong>Prvním krokem je vždy nastavení druhu a vzhledu podpisu.</strong> Pro seznámení s možnostmi jsme pro vás připravili krátké <strong><a href="/buildary-help-preview/diary/signaturesetting">videonávody</a></strong> v nápovědě pro modul Stavební deník. Nově si můžete vybrat ze 4 možností podepisování, a to jak přes webové rozhraní, tak v mobilní aplikaci. Ke stávajícímu způsobu podepisování přes externí editor Adobe Acrobat Reader, PDF-XChange Editor apod. (nově jako <strong>&quot;Možnost externí aplikace&quot;</strong>) přibyly 3 zcela nové způsoby, a to v aplikaci Buildary:</p><ul><li><strong><a href="/buildary-help-preview/diary/signaturesetting#buildary-certifikat">Podpis certifikátem Buildary</a></strong> - lze využívat u deníků, které nejsou vedeny ze zákona. Certifikát je vázaný na uživatele, ale není kvalifikovaný.</li><li><strong><a href="/buildary-help-preview/diary/signaturesetting#kvalifikovany-certifikat">Podpis kvalifikovaným certifikátem</a></strong> - doporučujeme využívat u deníků, které jsou vedeny ze zákona. Pro využití tohoto způsobu je potřeba nainstalovat si desktopovou aplikaci, která umožní použít kvalifikovaný certifikát či certifikát umístěný na tokenu. Po instalaci si vyberete certifikát, kterým chcete podepsat. Vše se vybraným certifikátem podepíše a uloží na server a vy si podepsané dny můžete zkontrolovat.</li><li><strong><a href="/buildary-help-preview/diary/signaturesetting#sluzba-remotesign">Podpis službou RemoteSign od I.CA</a></strong> - pro certifikáty vydané a uložené u I.CA lze využít vzdálené podepisování přes komerční aplikaci této společnosti. Aplikace po vás bude chtít zadat vaše ID u I.CA. Pro toto podepisování bude nutné mít nainstalovanou mobilní aplikaci RemoteSign od I.CA. Po zvolení možnosti „Podepsat“ se vám v mobilní aplikaci zobrazí nový požadavek pro podepsání dokumentu. Tento požadavek potvrdíte vaším heslem či PINem k této aplikaci. Dokumenty v řadě na podpis je nutné podepisovat postupně, každý požadavek zvlášť.</li></ul><p>Tyto možnosti lze použít jen do počtu nastavených podpisových polí. To znamená, že jsou-li nastavená 2 podpisová pole, bude každý případný další podpis nutné vložit přes externí aplikaci, vytvořením vlastního podpisového pole. Dále je nutné si u těchto možností nejprve zvolit vzhled podpisu (obrázek + text / jen obrázek / jen text).</p><p>Pro <strong><u>podpis jednoho dne</u></strong> je určená volba <strong>Podepsat</strong> pod časovou lištou. Pro požadavek hromadného <strong><u>podpisu více dní</u></strong> najednou je potřeba otevřít <strong>Další volby</strong> a zvolit možnost <strong>Podepsat více dní</strong>. Podmínky pro úspěšný podpis více dní najednou jsou podepsané Další záznamy svými autory a dny musí obsahovat záznamy.</p><p>Nemůže-li podepsání proběhnout dle požadavku, aplikace na tuto skutečnost upozorní i přes ikonu &quot;zvoneček&quot; v horní tmavé liště. Doposud byla tato ikona využívána pouze pro notifikace modulu Management úkolů.</p><p><strong>Nastavení podpisu je společné pro webovou i mobilní aplikaci. Ukládá se na serveru. Nastavení je možno upravit i v mobilní aplikaci. Vždy však je společné pro obě prostředí.</strong></p><ul><li><strong><a href="/buildary-help-preview/diary/externalappsignature">Podpis v externí aplikaci</a></strong> - podpis se provádí mimo aplikaci Buildary, např. v Adobe Acrobat Reader nebo PDF-XChange Editor apod.</li></ul><h2 id="zmeny-v-urovni-nastaveni-stavby" tabindex="-1">Změny v úrovni Nastavení stavby <a class="header-anchor" href="#zmeny-v-urovni-nastaveni-stavby" aria-label="Permalink to &quot;Změny v úrovni Nastavení stavby&quot;">​</a></h2><h3 id="cislo-objednavky" tabindex="-1">Číslo objednávky <a class="header-anchor" href="#cislo-objednavky" aria-label="Permalink to &quot;Číslo objednávky&quot;">​</a></h3><p>Do nastavení stavby jsme přidali kolonku pro vložení čísla objednávky. Číslo objednávky pak bude figurovat na Výzvách k platbě i následných Daňových dokladech.</p><h3 id="lokalizace-stavby-do-mapy-adresou" tabindex="-1">Lokalizace stavby do mapy adresou <a class="header-anchor" href="#lokalizace-stavby-do-mapy-adresou" aria-label="Permalink to &quot;Lokalizace stavby do mapy adresou&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+r+'" alt="" width="600" loading="lazy"><br></p></div><p>Při zakládání stavby bylo doposud nutné umístit ji přímo do mapy Google Maps. Nyní jsme přešli na využívání služby mapy.cz, která vám umožní zadat místo stavby přímo adresou, která se do mapy doplní sama, a naopak.</p><h3 id="hromadne-prirazeni-uzivatelu-do-deniku-stavby" tabindex="-1">Hromadné přiřazení uživatelů do deníků stavby <a class="header-anchor" href="#hromadne-prirazeni-uzivatelu-do-deniku-stavby" aria-label="Permalink to &quot;Hromadné přiřazení uživatelů do deníků stavby&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+d+'" alt="" width="600" loading="lazy"><br></p></div><p>Pokud máte na stavbě více deníků, museli jste každého nového uživatele přidávat samostatně na stavbu a samostatně do každého požadovaného deníku. Nyní budete mít možnost při přidání nového uživatele na stavbu zvolit i jednotlivé deníky, do kterých budete chtít danou osobu přidat.</p><h3 id="nahrada-uzivatele" tabindex="-1">Náhrada uživatele <a class="header-anchor" href="#nahrada-uzivatele" aria-label="Permalink to &quot;Náhrada uživatele&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+o+'" alt="" width="600" loading="lazy"><br></p></div><p>V Projektovém týmu stavby přibyla podzáložka Náhrada uživatele - v případě odchodu oprávněné osoby ze stavby a jeho nahrazením jinou osobou lze jednoduše původního uživatele zneplatnit a rovnou nahradit novým. Tato změna se projeví na všech denících, do kterých měl původní uživatel přístup.</p><h3 id="zakladani-a-parovani-sk-organizaci" tabindex="-1">Zakládání a párování SK organizací <a class="header-anchor" href="#zakladani-a-parovani-sk-organizaci" aria-label="Permalink to &quot;Zakládání a párování SK organizací&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+l+'" alt="" width="600" loading="lazy"><br></p></div><p>V České republice je možnost zadání organizace pomocí veřejných registrů již dobře známa. Nyní jsme tuto možnost připravili i pro Slovensko. Stačí zadat IČ nebo název firmy a aplikace vám další údaje doplní z registru.</p><h3 id="upresneni-fakturacnich-udaju" tabindex="-1">Upřesnění fakturačních údajů <a class="header-anchor" href="#upresneni-fakturacnich-udaju" aria-label="Permalink to &quot;Upřesnění fakturačních údajů&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+p+'" alt="" width="600" loading="lazy"><br></p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Prosíme všechny správce domén společností, které mají v aplikaci probíhající stavby, aby si zkontrolovali uvedené fakturační údaje.</strong></p></div><p>Pro společnosti působící na Slovensku jsme připravili pole pro doplnění hodnoty IČ DPH. Nyní je tato hodnota naplněna stejně jako DIČ. Také jsme připravili zatržítko pro plátce či neplátce DPH. Toto pole je předvyplněno jako plátce DPH.</p><p><strong>Doporučujeme provést kontrolu a potřebnou úpravu v údajích o firmě v Nastavení domén</strong></p><h2 id="zmeny-v-modulu-stavebni-denik" tabindex="-1">Změny v modulu Stavební deník <a class="header-anchor" href="#zmeny-v-modulu-stavebni-denik" aria-label="Permalink to &quot;Změny v modulu Stavební deník&quot;">​</a></h2><h3 id="chytry-kalendar" tabindex="-1">Chytrý kalendář <a class="header-anchor" href="#chytry-kalendar" aria-label="Permalink to &quot;Chytrý kalendář&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:200px;"><img src="'+v+'" alt="" width="200" loading="lazy"></div><p>Funkce kalendáře je zase o něco chytřejší. Potřebujete najít poslední podepsaný den nebo poslední den se záznamem? Není problém. Příslušný měsíc najdete na 2 kliknutí, i kdyby se jednalo o vzdálenou historii.</p><h3 id="kopirovani-mezi-deniky-ruznych-staveb" tabindex="-1">Kopírování mezi deníky různých staveb <a class="header-anchor" href="#kopirovani-mezi-deniky-ruznych-staveb" aria-label="Permalink to &quot;Kopírování mezi deníky různých staveb&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><p><img src="'+u+'" alt="" width="600" loading="lazy"><br></p></div><p>Kopírování mezi různými úrovněmi deníků jedné stavby mají naši uživatelé k dispozici již dlouho. Vzhledem k rozšiřujícím se počtům uživatelů a zhotovitelů, jsme pro vás připravili i možnost kopírování mezi deníky různých staveb. Administrátor či správce stavby může povolit kopírování dat ze svého deníku do deníku jiné stavby zadáním ID deníku, do kterého chce data kopírovat. <strong>Podmínkou pro kopírování je stejné nastavení povinných údajů v obou denících tak, aby i při kopírování tyto hodnoty byly vyplněné.</strong></p><h3 id="vyhledavani-nepodepsanych-zaznamu" tabindex="-1">Vyhledávání nepodepsaných záznamů <a class="header-anchor" href="#vyhledavani-nepodepsanych-zaznamu" aria-label="Permalink to &quot;Vyhledávání nepodepsaných záznamů&quot;">​</a></h3><div class="wiki-float wiki-float-left" style="--w:600px;"><img src="'+m+'" alt="" width="600" loading="lazy"></div><p>V okně pro vyhledávání v deníku máte možnost <strong>vyhledávat i podepsané a nepodepsané záznamy</strong>. Musíte zvolit Další záznamy a vybrat autora. Informace o tom, zda záznam je podepsán nebo ne, je přidána i v <strong>Exportu do Excelu</strong>.</p><h3 id="dalsi-zaznamy-maji-novy-format-sablony" tabindex="-1">Další záznamy mají nový formát šablony <a class="header-anchor" href="#dalsi-zaznamy-maji-novy-format-sablony" aria-label="Permalink to &quot;Další záznamy mají nový formát šablony&quot;">​</a></h3><p>Doposud byla šablona s hlavičkou pro vlastnoručně podepisované Další záznamy k dispozici pouze v PDF formátu. Tento však nebyl příliš použitelný pro možnost elektronického zápisu. Proto jsme přidali možnost stáhnout si šablonu ve formátu Word (.docx).</p><h3 id="novy-dochazkovy-system" tabindex="-1">Nový docházkový systém <a class="header-anchor" href="#novy-dochazkovy-system" aria-label="Permalink to &quot;Nový docházkový systém&quot;">​</a></h3><p>Ke stávajícím, již napojeným docházkovým systémům ConVision, Sysdo, WinPack a Kerosin jsme přidali další docházkový systém: ADAM.</p><h2 id="zmeny-v-modulu-soupisy-provedenych-praci" tabindex="-1">Změny v modulu Soupisy provedených prací <a class="header-anchor" href="#zmeny-v-modulu-soupisy-provedenych-praci" aria-label="Permalink to &quot;Změny v modulu Soupisy provedených prací&quot;">​</a></h2><h3 id="import-rozpoctu-s-oznacenim-chybnych-hodnot" tabindex="-1">Import rozpočtu s označením chybných hodnot <a class="header-anchor" href="#import-rozpoctu-s-oznacenim-chybnych-hodnot" aria-label="Permalink to &quot;Import rozpočtu s označením chybných hodnot&quot;">​</a></h3><p><img src="'+k+'" alt="" width="600" loading="lazy"><br></p><p>Při importu rozpočtu do SPP, který obsahoval chyby, nebylo z chybové hlášky úplně zřejmé, kde a jakou chybu v importu hledat. Pro zjednodušení a přehlednost je nyní z výsledku zřejmé, zda k importu došlo v pořádku / s upozorněními, nebo ne. Zobrazením importovaného souboru je pak možné zjistit, které buňky obsahují jaké chyby. Zároveň jsou všechny importované verze rozpočtu ukládány a je možné si je kdykoliv stáhnout.<br><img src="'+c+'" alt="" width="600" loading="lazy"></p>',51)])])}const x=e(h,[["render",y]]);export{_ as __pageData,x as default};
